from solution import get_closest_vowel
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

VOWELS = set("aeiouAEIOU")

def reference(word):
    # Obviously-correct model directly from spec:
    # scan from right, indices 1..len-2, vowel between two consonants
    for i in range(len(word) - 2, 0, -1):
        if word[i] in VOWELS and word[i - 1] not in VOWELS and word[i + 1] not in VOWELS:
            return word[i]
    return ""


# ---- explicit spec examples ----
def test_example_yogurt():
    assert get_closest_vowel("yogurt") == "u"

def test_example_FULL():
    assert get_closest_vowel("FULL") == "U"

def test_example_quick():
    assert get_closest_vowel("quick") == ""

def test_example_ab():
    assert get_closest_vowel("ab") == ""


# ---- boundaries: length, beginning/ending ----
def test_empty_string_returns_empty():
    assert get_closest_vowel("") == ""

def test_single_letter_returns_empty():
    for w in ["a", "b", "A", "Z", "e", "U"]:
        assert get_closest_vowel(w) == ""

def test_two_letters_returns_empty():
    for w in ["ab", "ba", "ae", "AA", "bb", "Ub"]:
        assert get_closest_vowel(w) == ""

def test_vowel_at_beginning_does_not_count():
    # 'a' at index 0 even if flanked on right by consonant can't count (no left)
    assert get_closest_vowel("ab") == ""
    assert get_closest_vowel("at") == ""
    assert get_closest_vowel("Abc") == ""

def test_vowel_at_ending_does_not_count():
    # ending vowel has no right neighbor
    assert get_closest_vowel("ba") == ""
    assert get_closest_vowel("bA") == ""
    assert get_closest_vowel("baba") == "a"  # rightmost qualifying is index 2, not ending index 3
    assert get_closest_vowel("babA") == "a"

def test_minimal_qualifying_length_three():
    assert get_closest_vowel("bab") == "a"
    assert get_closest_vowel("bAb") == "A"
    assert get_closest_vowel("bac") == "a"
    assert get_closest_vowel("abc") == ""
    assert get_closest_vowel("aaa") == ""
    assert get_closest_vowel("bbb") == ""

def test_case_sensitive_vowel_detection():
    for v in ["a", "e", "i", "o", "u", "A", "E", "I", "O", "U"]:
        w = "b" + v + "b"
        assert get_closest_vowel(w) == v

def test_case_preserved_on_return_FULL():
    # regression: lowercasing then returning lower breaks uppercase
    assert get_closest_vowel("FULL") == "U"
    assert get_closest_vowel("BAB") == "A"
    assert get_closest_vowel("bEb") == "E"
    assert get_closest_vowel("yOgUrt") == "U"

def test_y_is_consonant_not_vowel():
    assert get_closest_vowel("byb") == ""
    assert get_closest_vowel("bYb") == ""
    assert get_closest_vowel("yay") == ""
    # y as neighbor counts as consonant
    assert get_closest_vowel("yay") == ""  # middle a? no: y a y -> a between consonants -> should be "a"
    assert get_closest_vowel("yay") == "a"
    assert get_closest_vowel("yoy") == "o"
    assert get_closest_vowel("YOY") == "O"

def test_vowel_between_vowel_and_consonant_does_not_count():
    assert get_closest_vowel("baaab") == ""
    assert get_closest_vowel("baab") == ""
    assert get_closest_vowel("bAab") == ""

def test_rightmost_wins():
    assert get_closest_vowel("babeb") == "e"
    assert get_closest_vowel("bebAb") == "A"
    assert get_closest_vowel("bAbeb") == "e"
    assert get_closest_vowel("yogurt") == "u"
    # left qualifies but right also qualifies -> right wins
    assert get_closest_vowel("bAbebIb") == "I"


# ---- property-based tests vs reference model ----
letters = st.text(alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", min_size=0, max_size=12)

@given(letters)
def test_property_matches_reference_model(word):
    assert get_closest_vowel(word) == reference(word)

@given(letters)
def test_property_result_is_empty_or_single_vowel_in_word(word):
    r = get_closest_vowel(word)
    assert isinstance(r, str)
    assert len(r) <= 1
    if r == "":
        return
    assert r in VOWELS
    assert r in word  # case-sensitive containment

@given(letters)
def test_property_nonempty_result_is_between_consonants(word):
    r = get_closest_vowel(word)
    if r == "":
        return
    # find rightmost qualifying index per reference and check equality
    found = reference(word)
    assert r == found
    # verify structural condition at that index
    # there must exist i in 1..len-2 with word[i]==r and neighbors consonants
    ok = any(
        word[i] == r and word[i] in VOWELS and word[i-1] not in VOWELS and word[i+1] not in VOWELS
        for i in range(1, len(word) - 1)
    )
    assert ok

@given(letters)
def test_property_empty_iff_no_qualifying_position(word):
    r = get_closest_vowel(word)
    qualifying = [
        i for i in range(1, len(word) - 1)
        if word[i] in VOWELS and word[i-1] not in VOWELS and word[i+1] not in VOWELS
    ]
    if not qualifying:
        assert r == ""
    else:
        assert r == word[max(qualifying)]

@given(st.text(alphabet="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", min_size=3, max_size=10))
def test_property_rightmost_no_qualifier_to_its_right(word):
    r = get_closest_vowel(word)
    if r == "":
        return
    # locate returned position as rightmost occurrence matching reference
    # ensure no qualifying vowel strictly to the right
    # find index of the rightmost qualifying vowel
    qual = [i for i in range(1, len(word)-1)
            if word[i] in VOWELS and word[i-1] not in VOWELS and word[i+1] not in VOWELS]
    assert qual
    assert word[qual[-1]] == r
    # everything right of qual[-1] is non-qualifying
    for j in range(qual[-1]+1, len(word)-1):
        is_qual = word[j] in VOWELS and word[j-1] not in VOWELS and word[j+1] not in VOWELS
        assert not is_qual

@given(st.text(alphabet="bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ", min_size=1, max_size=6))
def test_property_all_consonants_returns_empty(cons):
    assert get_closest_vowel(cons) == ""

@given(st.text(alphabet="aeiouAEIOU", min_size=0, max_size=8))
def test_property_all_vowels_returns_empty(vows):
    # all-vowel strings have no consonant neighbors (except len<3 anyway)
    assert get_closest_vowel(vows) == ""
